<script setup>
import {computed,ref} from 'vue'

import ResponseViewer from './ResponseViewer.vue'
import {sseSelection} from './responseModel.js'
const props=defineProps({events:{type:Array,default:()=>[]},active:Boolean,canAssert:Boolean,canExtract:Boolean}),emit=defineEmits(['assert','extract'])
const search=ref(''),eventType=ref(''),selected=ref(null)
const types=computed(()=>[...new Set(props.events.map(e=>e.event||'message'))].map(v=>({value:v,label:v})))
const rows=computed(()=>props.events.map((e,index)=>({...e,index,key:index,event:e.event||'message'})).filter(e=>(!eventType.value||e.event===eventType.value)&&(!search.value||(e.id+' '+e.event+' '+e.data).toLowerCase().includes(search.value.toLowerCase()))))
function selection(){return sseSelection(props.events,selected.value.index)}
function assertion(field){emit('assert',{...field,type:'sse_json',...selection()});selected.value=null}
function extraction(field){emit('extract',{...field,source:'sse',...selection()});selected.value=null}

import OptionPicker from '../shared/components/OptionPicker.vue'



import {Badge,Button,Empty,EmptyContent,EmptyDescription,EmptyHeader,Input,Sheet,SheetContent,SheetDescription,SheetFooter,SheetHeader,SheetTitle,Table,TableBody,TableCell,TableHead,TableHeader,TableRow} from '../shared/shadcn-ui.js'

import {InputGroup,InputGroupInput,InputGroupAddon,InputGroupButton} from '../shared/shadcn-ui.js'

import {XIcon} from '@lucide/vue'
</script>
<template><section class="sse-viewer"><div class="event-tools flex flex-wrap items-center gap-2"><OptionPicker v-model="eventType" placeholder="全部事件类型" aria-label="筛选 SSE 事件类型" style="width:200px" :options="types" all-label="不限"/><InputGroup style="width:260px" class="min-w-0 "><InputGroupInput v-model="search" placeholder="搜索事件 ID 或数据" aria-label="搜索 SSE 事件"/><InputGroupAddon align="inline-end"><InputGroupButton v-if="search" :disabled="false" size="icon-xs" aria-label="清空输入" @click="search='' "><XIcon/></InputGroupButton></InputGroupAddon></InputGroup><Badge variant="secondary">{{rows.length}} / {{events.length}} 条</Badge><Badge v-if="active" :variant="(&quot;blue&quot;)==='red'?'destructive':'secondary'">持续接收中</Badge></div><div class="min-w-0 max-w-full"><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({x:600,y:420}).y?({x:600,y:420}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({x:600,y:420}).x||({x:600,y:420}).minWidth||490)+'px'}"><TableHeader><TableRow><TableHead :style="{width:(55)+'px'}">#</TableHead><TableHead :style="{width:(170)+'px'}">事件类型 / ID</TableHead><TableHead>数据</TableHead><TableHead :style="{width:(115)+'px'}">操作</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (rows||[])" :key="typeof (&quot;key&quot;)==='function'?(&quot;key&quot;)(record):record[&quot;key&quot;]??rowIndex"><TableRow><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]">{{record.index+1}}</template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]">{{record.event}}<div class="event-id">{{record.id||'—'}}</div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><pre>{{record.data}}</pre></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><Button @click="selected=record" variant="ghost" size="default" type="button">查看字段</Button></template></div></TableCell></TableRow></template><TableRow v-if="!(rows||[]).length"><TableCell :colspan="4"><Empty><EmptyHeader><EmptyDescription>{{active?'等待匹配事件':'没有匹配的事件'}}</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div></div><Sheet :open="!!selected" @update:open="async v=>{if(!v){selected=null}}"><SheetContent class="data-[side=right]:w-full gap-0 overflow-hidden p-0 data-[side=right]:sm:max-w-[var(--editor-width)]" :class="false?'inset-0 h-dvh max-h-dvh w-screen max-w-none translate-x-0 translate-y-0 rounded-none sm:max-w-none':''" :style="{'--editor-width':typeof ('min(850px,95vw)')==='number'?('min(850px,95vw)')+'px':('min(850px,95vw)')}" :show-close-button="true" @interact-outside="e=>{e.preventDefault()}"><SheetHeader class="shrink-0 border-b p-5 pr-12"><SheetTitle>{{'事件详情 · '+(selected?.event||'message')+' #'+((selected?.index||0)+1)}}</SheetTitle><SheetDescription class="sr-only">详情与操作</SheetDescription></SheetHeader><div class="min-h-0 flex-1 overflow-auto p-5"><ResponseViewer v-if="selected" :key="selected.index" :body="selected.data" :can-assert="canAssert&&!active" :can-extract="canExtract&&!active" @assert="assertion" @extract="extraction"/></div></SheetContent></Sheet></section></template>
<style scoped>.event-tools{margin-bottom:12px}.event-id{color:var(--muted-foreground);font-size:.75rem}pre{margin:0;white-space:pre-wrap;overflow-wrap:anywhere;max-height:90px;overflow:auto;font-family:var(--mono);font-size:.75rem}</style>
